/* Desktop workspace shell; business rules and stored records remain in their existing modules. */
(function(){
 const shared=document.body.classList.contains('shared-app');
 let layout=localStorage.getItem('samandis-layout-v2')||'list';
 const icons={work:'<rect x="4" y="5" width="16" height="15" rx="3"/><path d="M9 5V3h6v2M4 10h16M10 10v3h4v-3"/>',mine:'<rect x="4" y="4" width="16" height="16" rx="3"/><path d="m8 12 3 3 5-6"/>',all:'<path d="M9 6h11M9 12h11M9 18h11M4 6h.1M4 12h.1M4 18h.1"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v5M17 3v5M3 11h18M8 15h2M14 15h2"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2M16 5a3 3 0 0 1 0 6M18 15a5 5 0 0 1 3 5"/>',chart:'<path d="M4 3v18h17M8 16v-4M13 16V7M18 16V4"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',chevron:'<path d="m9 5 7 7-7 7"/>',list:'<path d="M8 6h12M8 12h12M8 18h12M3 6h1M3 12h1M3 18h1"/>',board:'<rect x="3" y="4" width="7" height="16" rx="1.5"/><rect x="14" y="4" width="7" height="11" rx="1.5"/>',plus:'<path d="M12 5v14M5 12h14"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',arrow:'<path d="m5 12 5 5L20 7"/>'};
 const ico=n=>`<svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.work}</svg>`;
 const q=s=>document.querySelector(s);
 document.body.classList.add('desktop-shell');
 document.body.insertAdjacentHTML('afterbegin',`<aside id="desktopSidebar" class="desktop-sidebar"><a class="desk-brand" href="${shared?'shared.html':'index.html'}"><img src="samandis.jpg" alt="سمندیس"><span>سمندیس<small>مدیریت پروژه‌ها</small></span></a><button class="desk-project" id="deskProject"><span class="project-glyph">${ico('work')}</span><span><b>پروژه دارایی</b><small>فضای کاری شرکت سمندیس</small></span>${ico('chevron')}</button><div class="desk-project-pop" id="deskProjectPop" hidden><b>پروژه دارایی</b><p>پروژه‌های بعدی اینجا اضافه می‌شوند.</p></div><button class="desk-add" id="deskNewTask">${ico('plus')}<span>کار جدید</span><kbd>N</kbd></button><div class="desk-nav-label">فضای کاری</div><nav id="deskNav">${[['mine','mine','کارهای من'],['all','all','همه کارها'],['program','calendar','تقویم و برنامه']].map(([v,i,l])=>`<button data-desk-view="${v}">${ico(i)}<span>${l}</span><b data-desk-count="${v}"></b></button>`).join('')}</nav><div id="deskManage"><div class="desk-nav-label">مدیریت پروژه</div><button data-desk-view="members">${ico('users')}<span>اعضای پروژه</span></button><button data-desk-view="reports">${ico('chart')}<span>گزارش افراد</span></button></div><div class="desk-project-preview"><img src="project-facade.jpg" alt="نمای پروژه دارایی"><span>پروژه دارایی<small lang="en" dir="ltr">We plan. We build.</small></span></div><div class="desk-bottom"><div id="deskIdentity"></div><a class="desk-mode-link" href="${shared?'index.html':'shared.html'}">${shared?'مشاهده نمونه آزمایشی':'ورود به فضای مشترک'} ${ico('chevron')}</a><small>${shared?'ورود امن · فضای مشترک':'نمونه آزمایشی · ذخیره در مرورگر'}</small></div></aside><button id="deskOverlay" class="desk-overlay" aria-label="بستن منو"></button>`);
 const header=q('main>header');header.insertAdjacentHTML('afterbegin',`<div class="desk-top-context"><button id="deskMenu" class="desk-icon-button" aria-label="بازکردن منو">${ico('menu')}</button><span class="desk-top-project">پروژه دارایی</span><span class="desk-crumb-slash">/</span><b id="deskCrumb">کارهای من</b></div>`);
 header.insertAdjacentHTML('beforeend',`<div class="desk-top-actions"><span id="deskDate"></span><button id="deskSearch" class="desk-icon-button" aria-label="جست‌وجوی کار">${ico('search')}<kbd>/</kbd></button></div>`);
 const mobileQuery=window.matchMedia('(max-width:760px)');function syncMenu(){const open=document.body.classList.contains('desk-menu-open');q('#desktopSidebar').inert=mobileQuery.matches&&!open;q('#deskMenu').setAttribute('aria-expanded',String(open));q('#deskMenu').setAttribute('aria-controls','desktopSidebar')}q('#deskMenu').onclick=()=>{document.body.classList.toggle('desk-menu-open');syncMenu()};q('#deskOverlay').onclick=()=>{document.body.classList.remove('desk-menu-open');syncMenu()};mobileQuery.addEventListener('change',syncMenu);syncMenu();
 q('#deskProject').onclick=()=>q('#deskProjectPop').hidden=!q('#deskProjectPop').hidden;
 q('#deskDate').textContent=new Intl.DateTimeFormat('fa-IR',{day:'numeric',month:'long',timeZone:'Asia/Tehran'}).format(new Date());
 function closeMenu(){document.body.classList.remove('desk-menu-open');syncMenu()}
 function focusSearch(){const input=q(shared?'#sharedSearch':'#claritySearch');if(input){input.focus();input.scrollIntoView({block:'center',behavior:'smooth'})}}
 q('#deskSearch').onclick=focusSearch;document.body.insertAdjacentHTML('beforeend','<button class="desk-mobile-add" id="deskMobileAdd" aria-label="کار جدید">'+ico('plus')+'</button>');q('#deskMobileAdd').onclick=()=>q('#deskNewTask').click();
 const names={mine:'کارهای من',all:'همه کارها',program:'تقویم و برنامه',members:'اعضای پروژه',reports:'گزارش افراد'};
 function updateNav(current,manage,personal,total){q('#deskCrumb').textContent=names[current]||'فضای کاری';q('#deskManage').hidden=!manage;q('#deskMobileAdd').hidden=shared&&!mine();q('[data-desk-count="mine"]').textContent=personal;q('[data-desk-count="all"]').textContent=total;document.querySelectorAll('[data-desk-view]').forEach(b=>b.classList.toggle('active',b.dataset.deskView===current))}
 function metricsHTML(counts){return `<div class="desk-metrics">${[['open','در دست انجام','blue'],['review','منتظر تأیید','yellow'],['done','تمام‌شده','purple']].map(([k,l,c])=>`<button class="desk-metric ${c}" data-desk-phase="${k}"><span class="metric-symbol">${ico(k==='done'?'arrow':k==='review'?'users':'work')}</span><span>${l}<b>${counts[k]}</b></span><span class="metric-mini">${ico('chevron')}</span></button>`).join('')}</div>`}
 function layoutHTML(){return `<div class="desk-layout" aria-label="نمایش کارها"><button data-desk-layout="list" class="${layout==='list'?'active':''}" aria-label="نمای فهرست">${ico('list')}</button><button data-desk-layout="board" class="${layout==='board'?'active':''}" aria-label="نمای برد">${ico('board')}</button></div>`}
 if(!shared){
  const profile=q('.role-label');q('#deskIdentity').append(profile);
  q('#deskNewTask').onclick=()=>{closeMenu();openSimpleEditor()};q('.desk-top-actions').insertAdjacentHTML('afterbegin','<button class="secondary" id="deskDelivery" hidden>＋ ثبت تحویل</button>');q('#deskDelivery').onclick=()=>openDelivery();
  document.querySelectorAll('[data-desk-view]').forEach(b=>b.onclick=()=>{closeMenu();navigate(b.dataset.deskView)});
  const previousTasks=renderTasks;
  renderTasks=function(){previousTasks();const scoped=clarityScope(),counts={};for(const phase of ['open','review','done'])counts[phase]=num(scoped.filter(t=>clarityPhase(t)===phase).length);q('.clarity-list-head').insertAdjacentHTML('afterend',metricsHTML(counts));q('.clarity-list-head').insertAdjacentHTML('afterbegin','<div class="desk-page-eyebrow">فضای کاری / '+(view==='mine'?'شخصی':'پروژه دارایی')+'</div>');q('.clarity-tools').insertAdjacentHTML('beforeend',layoutHTML());document.querySelectorAll('[data-desk-phase]').forEach(b=>b.onclick=()=>{clarityStatus=b.dataset.deskPhase;renderTasks()});document.querySelectorAll('[data-desk-layout]').forEach(b=>b.onclick=()=>{layout=b.dataset.deskLayout;localStorage.setItem('samandis-layout-v2',layout);renderTasks()});if(layout==='board'){
   const list=scoped.filter(t=>(clarityStatus==='all'||clarityPhase(t)===clarityStatus)&&(!simpleQuery||(t.title+' '+t.description+' '+taskCode(t)).includes(simpleQuery))&&(!simpleOwner||t.owner===Number(simpleOwner)));
   q('.clarity-list').innerHTML=`<div class="desk-board">${[['open','در دست انجام'],['review','منتظر تأیید'],['done','تمام‌شده']].map(([phase,label])=>{const group=list.filter(t=>clarityPhase(t)===phase);return `<section class="desk-lane ${phase}"><h3><span class="lane-dot"></span>${label}<b>${num(group.length)}</b></h3>${group.map(t=>`<article class="desk-task-card"><div class="card-top">${clarityCheck(t)}<span dir="ltr">${taskCode(t)}</span></div><button class="task-title" data-task="${esc(t.id)}">${esc(t.title)}</button><p>${esc(t.description?.slice(0,90)||'برای مشاهده جزئیات، کار را باز کنید.')}</p><div class="card-bottom">${person(t.owner)}<span>${fmt(t.due)}</span></div>${canContribute(t)&&t.status!=='بسته‌شده'?`<button class="row-upload" data-upload-task="${esc(t.id)}">↑ بارگذاری فایل</button>`:''}${canApproveTask(t)?`<button class="approve-inline" data-quick-approve="${esc(t.id)}">تأیید نهایی</button>`:''}</article>`).join('')||'<div class="lane-empty">کاری در این وضعیت نیست</div>'}</section>`}).join('')}</div>`;
  }};
  const previousRender=render;render=function(){previousRender();updateNav(view,manager(),num(clarityScope('mine').length),num(tasks.length));q('#deskNewTask').hidden=['reports','members'].includes(view);q('#deskDelivery').hidden=!(view==='program'&&manager());};
  // Always open the current user's work, preserving every stored record.
  render();
 }else{
  q('#deskNewTask').onclick=()=>{closeMenu();if(mine())createTaskForm();else q('#loginForm input')?.focus()};
  document.querySelectorAll('[data-desk-view]').forEach(b=>b.onclick=()=>{closeMenu();if(!mine()){message('ابتدا با حساب خود وارد شوید.');return}scope=b.dataset.deskView;phase='all';search='';render()});
  let sharedCalendarAnchor=new Date();
  renderProgram=function(){
   const dateKey=d=>d.toISOString().slice(0,10),add=(d,n)=>new Date(d.getTime()+n*86400000),part=d=>Object.fromEntries(new Intl.DateTimeFormat('en-US-u-ca-persian',{year:'numeric',month:'numeric',day:'numeric',timeZone:'UTC'}).formatToParts(d).filter(p=>p.type!=='literal').map(p=>[p.type,Number(p.value)]));
   const anchor=new Date(dateKey(sharedCalendarAnchor)+'T12:00:00Z'),start=add(anchor,1-part(anchor).day);let end=start;while(part(add(end,1)).month===part(start).month)end=add(end,1);
   const cells=Array((start.getUTCDay()+1)%7).fill('<div class="calendar-cell blank"></div>');
   for(let d=start;d<=end;d=add(d,1)){const key=dateKey(d),events=tasks.filter(t=>t.due===key);cells.push(`<div class="calendar-cell ${key===dateKey(new Date())?'is-today':''}"><span class="day-number">${fa(part(d).day)}</span>${events.map(t=>`<button class="cal-event ${t.status==='done'?'completed':''}" data-shared-calendar-task="${t.id}">${esc(t.title)}</button>`).join('')}</div>`)}
   while(cells.length%7)cells.push('<div class="calendar-cell blank"></div>');
   el('#sharedContent').innerHTML=`<section class="panel"><div class="panel-header"><h2>تقویم شمسی پروژه</h2><div class="calendar-tools"><button id="sharedPrevMonth" aria-label="ماه قبل">→</button><b>${new Intl.DateTimeFormat('fa-IR',{month:'long',year:'numeric',timeZone:'UTC'}).format(start)}</b><button id="sharedNextMonth" aria-label="ماه بعد">←</button><button id="sharedToday">امروز</button></div></div><div class="calendar-panel"><div class="calendar-grid">${['شنبه','یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنجشنبه','جمعه'].map(n=>`<div class="weekday">${n}</div>`).join('')}${cells.join('')}</div></div></section>`;
   el('#sharedPrevMonth').onclick=()=>{sharedCalendarAnchor=add(start,-1);renderProgram()};el('#sharedNextMonth').onclick=()=>{sharedCalendarAnchor=add(end,1);renderProgram()};el('#sharedToday').onclick=()=>{sharedCalendarAnchor=new Date();renderProgram()};document.querySelectorAll('[data-shared-calendar-task]').forEach(b=>b.onclick=()=>detail(b.dataset.sharedCalendarTask));
  };
  const previousSharedRender=render;
  render=function(){previousSharedRender();if(!project||!mine())return;updateNav(scope,management(),fa(tasks.filter(t=>own(t)||collaborating(t)).length),fa(tasks.length));q('#deskIdentity').innerHTML=`<span class="desk-user-avatar">${esc(mine().name[0])}</span><div><b>${esc(mine().name)}</b><small>${esc(mine().title)}</small></div>`;q('#deskNewTask').hidden=false;
   if(['mine','all'].includes(scope)){const ts=tasks.filter(t=>scope==='all'||own(t)||collaborating(t)),counts={};for(const status of ['open','review','done'])counts[status]=fa(ts.filter(t=>t.status===status).length);q('#sharedContent').insertAdjacentHTML('afterbegin',`<div class="desk-shared-heading"><small>فضای کاری / ${scope==='mine'?'شخصی':esc(project.name)}</small><h1>${names[scope]}</h1><p>${scope==='mine'?'کارهایی که به شما سپرده شده یا با همکاری شما پیش می‌رود.':'همهٔ کارهای تیم، در یک نگاه.'}</p></div>`+metricsHTML(counts));document.querySelectorAll('[data-desk-phase]').forEach(b=>b.onclick=()=>{phase=b.dataset.deskPhase;render()});
    q('.shared-subtools').insertAdjacentHTML('beforeend',layoutHTML());document.querySelectorAll('[data-desk-layout]').forEach(b=>b.onclick=()=>{layout=b.dataset.deskLayout;localStorage.setItem('samandis-layout-v2',layout);render()});
    if(layout==='board'){
     const list=ts.filter(t=>(phase==='all'||t.status===phase)&&(t.title+' '+t.description).includes(search));
     const target=q('#sharedContent .clarity-list')||q('#sharedContent .shared-empty');
     if(target){target.className='clarity-list';target.innerHTML=`<div class="desk-board">${Object.entries(labels).map(([state,label])=>{const group=list.filter(t=>t.status===state);return `<section class="desk-lane ${state}"><h3><span class="lane-dot"></span>${label}<b>${fa(group.length)}</b></h3>${group.map(t=>`<article class="desk-task-card"><div class="card-top"><button class="task-tick ${t.status}" data-shared-complete="${t.id}" role="checkbox" aria-checked="${t.status!=='open'}" aria-label="وضعیت ${esc(t.title)}" ${t.status==='done'?!reviewer(t)?'disabled':'':!own(t)&&!canManage(t)?'disabled':''}>${t.status==='open'?'':'✓'}</button></div><button class="task-title" data-shared-card="${t.id}">${esc(t.title)}</button><p>${esc(t.description.slice(0,90))}</p><div class="card-bottom"><span>${esc(person(t.owner_id))}</span><span>${date(t.due)}</span></div>${contribute(t)&&t.status!=='done'?`<button class="row-upload" data-shared-upload="${t.id}">↑ بارگذاری فایل</button>`:''}</article>`).join('')||'<div class="lane-empty">کاری در این وضعیت نیست</div>'}</section>`}).join('')}</div>`;}
     document.querySelectorAll('[data-shared-card]').forEach(b=>b.onclick=()=>detail(b.dataset.sharedCard));document.querySelectorAll('[data-shared-upload]').forEach(b=>b.onclick=()=>detail(b.dataset.sharedUpload,true));document.querySelectorAll('[data-shared-complete]').forEach(b=>b.onclick=()=>{const t=tasks.find(t=>t.id===b.dataset.sharedComplete);action(t,t.status==='open'?'submit':'reopen')});
    }
   }
  };
  const previousAuth=authForm;authForm=function(note=''){previousAuth(note);updateNav('mine',false,'','');q('#deskIdentity').innerHTML='<span class="desk-user-avatar">'+ico('users')+'</span><div><b>فضای مشترک سمندیس</b><small>ورود با حساب شخصی</small></div>';q('#deskNewTask').hidden=true;};
  if(project&&mine())render();else if(!session)authForm();
 }
 document.addEventListener('keydown',e=>{if(e.altKey||e.ctrlKey||e.metaKey||e.target.closest('input,textarea,select,[contenteditable="true"]'))return;if(e.key==='Escape'){closeMenu();return}if(e.key==='/'){e.preventDefault();focusSearch()}if(e.key.toLowerCase()==='n'&&!document.querySelector('dialog[open]')){e.preventDefault();q('#deskNewTask').click()}});
})();
/* Keep task attachments prominent in both application modes. */
(function(){
 const shared=document.body.classList.contains('shared-app'),previousDetail=detail;
 detail=async function(...args){await previousDetail(...args);const root=document.querySelector(shared?'#sharedDetail':'#detailBody');if(!root)return;const form=root.querySelector(shared?'#sharedUpload':'#versionForm');if(!form)return;root.querySelector('#desktopUploadShortcut')?.remove();const button=document.createElement('button');button.type='button';button.id='desktopUploadShortcut';button.className='desktop-upload-shortcut';button.textContent='↑ بارگذاری فایل برای این کار';button.onclick=()=>{const disclosure=form.querySelector('details');if(disclosure)disclosure.open=true;const dialog=document.querySelector(shared?'#sharedDialog':'#details');dialog.scrollTo({top:Math.max(0,form.offsetTop-45),behavior:'smooth'});form.querySelector('input[type="file"]')?.focus({preventScroll:true})};const head=root.querySelector(shared?'.shared-task-head':'.dialog-head');if(head)head.after(button);
 };
})();

(function(){
 const shared=document.body.classList.contains('shared-app'),previous=detail;
 const grip=document.createElement('button');grip.type='button';grip.className='detail-edge-grip';grip.setAttribute('aria-label','بستن پنل جزئیات');grip.title='بستن پنل · کلیک یا کشیدن به کنار';grip.innerHTML='<span>‹</span><i></i>';document.body.append(grip);
 function close(){const button=document.querySelector(shared?'#sharedClose':'#closeTask');if(button)button.click();else document.querySelector(shared?'#sharedDialog':'#details')?.close();document.body.classList.remove('task-drawer-open');grip.hidden=true}
 grip.onclick=close;let startX=null;grip.onpointerdown=e=>{startX=e.clientX;grip.setPointerCapture(e.pointerId)};grip.onpointermove=e=>{if(startX!==null&&e.clientX-startX< -35){startX=null;close()}};grip.onpointerup=()=>startX=null;grip.onpointercancel=()=>startX=null;
 function sync(){const dialog=document.querySelector(shared?'#sharedDialog':'#details');grip.hidden=!dialog?.open;if(dialog?.open){const r=dialog.getBoundingClientRect();grip.style.left=Math.max(0,r.right-1)+'px'}}
 detail=async function(...args){await previous(...args);sync()};new MutationObserver(sync).observe(document.querySelector(shared?'#sharedDialog':'#details'),{attributes:true,attributeFilter:['open']});window.addEventListener('resize',sync);sync();
})();
